$labels=['computer'=>'رایانه','printer'=>'چاپگر','display'=>'نمایشگر','scanner'=>'اسکنر'];$counts=[];foreach(array_keys($labels) as $t){$q=db()->prepare('SELECT COUNT(*) FROM assets WHERE asset_type=?');$q->execute([$t]);$counts[$t]=(int)$q->fetchColumn();}
